// 1. Define IPago, PagoTarjeta, PagoPayPal

// 2. Crea Carrito con set_Estrategia y ProcesarPago

class Program
{
    static void Main()
    {
        // 3. Ejecútalo
        Carrito carrito = new Carrito();
        carrito.SetEstrategia(new PagoTarjeta());
        carrito.ProcesarPago(100);

        carrito.SetEstrategia(new PagoPayPal());
        carrito.ProcesarPago(200);
    }
