using System;

interface IPago { void Pagar(int monto); }

class PagoTarjeta : IPago { public void Pagar(int monto) { Console.WriteLine($"Pagado {monto} con Tarjeta"); } }
class PagoPayPal : IPago { public void Pagar(int monto) { Console.WriteLine($"Pagado {monto} con PayPal"); } }

class Carrito {
    private IPago _pago;
    public Carrito(IPago pago) { _pago = pago; }
    public void SetEstrategia(IPago pago) { _pago = pago; }
    public void Procesar(int monto) { _pago.Pagar(monto); }
}

class Program {
    static void Main() {
        var c = new Carrito(new PagoTarjeta());
        c.Procesar(100);
        c.SetEstrategia(new PagoPayPal());
        c.Procesar(50);
    }
}
